import re

from moler.exceptions import ParsingDone
from moler.util.converterhelper import ConverterHelper

from ta_moler.cmd.shared.aashell.genericaashell import GenericAashell

__author__ = "Piotr Smerdzynski"
__copyright__ = "Copyright (C) 2020, Nokia"
__email__ = "piotr.smerdzynski@nokia.com"


class Nodes(GenericAashell):
    """nodes command class."""

    def __init__(self, connection, options=None, process=None, prompt=r"^AaShell>", newline_chars=None, runner=None):
        """
        Command nodes.

        :param connection: moler connection to device, terminal when command is executed
        :param options: parameter with which the command will be executed
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Nodes, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.current_ret = {}
        self._current_node = ""
        self.options = options
        self.process = process
        self._converter = ConverterHelper.get_converter_helper()

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "nodes"
        if self.options:
            cmd = f"{cmd} {self.options}"
            if self.process:
                cmd = f"{cmd} {self.process}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: calls super
        """
        if is_full_line:
            try:
                self._parse_node_header(line)
                self._parse_node_parameters(line)
                self._parse_start_of_processes_section(line)
                self._parse_node_processes(line)
            except ParsingDone:
                pass
        return super(Nodes, self).on_new_line(line, is_full_line)

    # --------------- node: 0x201B ----------------
    _re_node_header = re.compile(r"^[-]+\snode:\s(?P<NODE>.*)\s[-]+$")

    def _parse_node_header(self, line):
        """
        Add node id as key to result dict.

        :param line: line to be parsed
        """
        if self._regex_helper.search_compiled(Nodes._re_node_header, line):
            self._current_node = self._regex_helper.group("NODE")
            self.current_ret[self._current_node] = {}
            raise ParsingDone

    # ceName: NOT SET, ownNid: 0x201B, masterNid: 0x2011
    _re_node_parameters = re.compile(
        r"^(?P<ceName>\w+):\s(?P<ceName_value>[a-zA-Z ]+)\W+(?P<ownNid>\w+):\s"
        r"(?P<ownNid_value>\w+)\W+(?P<masterNid>\w+):\s(?P<masterNid_value>\w+)$"
    )

    def _parse_node_parameters(self, line):
        """
        Add node parameters to node dict.

        :param line: line to be parsed
        """
        if self._regex_helper.search_compiled(Nodes._re_node_parameters, line):
            self.current_ret[self._current_node][self._regex_helper.group("ceName")] = self._regex_helper.group("ceName_value")
            self.current_ret[self._current_node][self._regex_helper.group("ownNid")] = self._regex_helper.group("ownNid_value")
            self.current_ret[self._current_node][self._regex_helper.group("masterNid")] = self._regex_helper.group("masterNid_value")
            raise ParsingDone

    # Running processes:
    _re_processes_section = re.compile(r"^Running processes:$")

    def _parse_start_of_processes_section(self, line):
        """
        Detect start of processes section.

        :param line: line to be parsed
        """
        if self._regex_helper.search_compiled(Nodes._re_processes_section, line):
            self.current_ret[self._current_node]["processes"] = []
            raise ParsingDone

    # RROMexe
    _re_node_processes = re.compile(r"^\w+$")

    def _parse_node_processes(self, line):
        """
        Add processes running on current node.

        :param line: line to be parsed
        """
        if self._regex_helper.search_compiled(Nodes._re_node_processes, line):
            self.current_ret[self._current_node]["processes"].append(self._regex_helper.group(0))
            raise ParsingDone


