"""
================================================HELP=MESSAGE============================================================
AaShell> nodes -h

NAME:
    CC&S Shell nodes command
    Prints node related information for known nodes

USAGE:
    nodes [options]
    -h        Prints command help
    -p        Prints nodes related information and all running processes
    -p name   Prints nodes related information and running processes matching given name pattern
    -v        Makes '-p' and '-p name' verbose
    -c        Prints nodes related information and list of all installed commands
    -c name   Prints nodes related information and list of installed commands matching given name pattern
    -s        Makes '-c' and '-c name' short
    -i        Makes '-p name' and '-c name' case insensitive

EXAMPLES:
    nodes
    nodes -h
    nodes -p
    nodes -v -p
    nodes -p CCS
    nodes -i -p ccs
    nodes -c
    nodes -c -p CCS
    nodes -c msg
    nodes -s -c msg
    nodes -i -c msg
    nodes -s -i -c msg
    nodes -s -i -c msg -v -p ccs

AaShell>
"""
